# Generated by manage.py generate_test_cases.
from collections.abc import Callable
from urllib.parse import parse_qs, urlsplit

from django.contrib.contenttypes.models import ContentType
from django.urls import reverse
from playwright.sync_api import Error, Locator, Response, expect

from bloomerp.tests.base import (
    BloomerpE2ETestCase,
    E2EAction,
    E2ERequestScenario,
)
from bloomerp.utils.models import get_create_view_url


class TestBloomerpCreateViewE2E(BloomerpE2ETestCase):
    """Exercise native FK focus events through the real create form and Save."""

    view_name = "add"
    create_foreign_models = True
    auto_create_customers = False

    def get_test_scenarios(self) -> list[E2ERequestScenario]:
        """Run the same FK selection contract in full-page and modal forms."""
        return [
            self._selection_scenario(
                "Full-page FK selection enables Save and persists the relation",
                reverse(get_create_view_url(self.CountryModel)),
                self._use_full_page_form,
            ),
            self._selection_scenario(
                "Modal FK selection enables Save and returns the created object",
                reverse(get_create_view_url(self.CustomerModel)),
                self._open_country_modal,
            ),
        ]

    def _selection_scenario(
        self,
        name: str,
        url: str,
        open_form: Callable[[], None],
    ) -> E2ERequestScenario:
        """Describe real result activation, event propagation, reset, and Save."""
        return E2ERequestScenario(
            name=name,
            description=(
                "Restoring a portalled dropdown containing the focused result "
                "must not throw or suppress the widget/cell change events."
            ),
            user=self.admin_user,
            url=url,
            prepare=self._record_browser_errors,
            actions=[
                E2EAction(name="Open the pristine create form", execute=open_form),
                E2EAction(
                    name="Click a natively focused FK result",
                    execute=self._select_earth_with_mouse,
                ),
                E2EAction(
                    name="Reselect the same FK without another change event",
                    execute=self._reselect_earth_with_mouse,
                ),
                E2EAction(
                    name="Clear the FK and reset the form to its pristine state",
                    execute=self._clear_and_reset_relation,
                ),
                E2EAction(
                    name="Select another FK using the keyboard",
                    execute=self._select_mars_with_keyboard,
                ),
                E2EAction(
                    name="Save and verify the persisted FK",
                    execute=self._save_country,
                    validators=self._expect_no_browser_errors,
                ),
            ],
        )

    def _record_browser_errors(self) -> None:
        """Capture uncaught native browser errors before the scenario navigates."""
        self.browser_errors: list[str] = []
        self.page.on("pageerror", self._capture_browser_error)

    def _capture_browser_error(self, error: Error) -> None:
        """Retain uncaught errors, including dropdown restoration NotFoundError."""
        self.browser_errors.append(str(error))

    def _expect_no_browser_errors(self) -> None:
        """Require that real selection and submission produced no page errors."""
        self.assertEqual(self.browser_errors, [])

    def _use_full_page_form(self) -> None:
        """Observe the initially pristine full-page country create form."""
        self.in_modal = False
        self.form_host = self.page.locator("#main-content")
        self._observe_relation_events()

    def _open_country_modal(self) -> None:
        """Open a real country create dialog from the customer's country field."""
        country_widget = self.page.locator(
            '#main-content [bloomerp-component="foreign-field-widget"]'
            '[data-field-name="country"]'
        )
        country_widget.locator('input[type="text"]').focus()
        self.page.locator(
            '.foreign-field-dropdown:visible [data-action="create-new"]'
        ).click()
        self.in_modal = True
        self.form_host = self.page.locator(
            '[data-modal-instance-of="create-object-modal"]'
        )
        expect(self.form_host).to_have_count(1)
        self._observe_relation_events()

    def _planet_widget(self) -> Locator:
        """Locate the live relation widget inside this scenario's form."""
        return self.form_host.locator(
            '[bloomerp-component="foreign-field-widget"][data-field-name="planet"]'
        )

    def _observe_relation_events(self) -> None:
        """Count public events without replacing native focus or widget behavior."""
        widget = self._planet_widget()
        expect(widget.locator('input[type="text"]')).to_be_visible()
        expect(self.form_host.locator("#object-crud-container-buttons")).to_be_hidden()
        widget.evaluate(
            """widget => {
                widget.dataset.observedWidgetChanges = '0';
                widget.dataset.observedCellChanges = '0';
                widget.addEventListener('bloomerp:widget-change', () => {
                    widget.dataset.observedWidgetChanges = String(
                        Number(widget.dataset.observedWidgetChanges) + 1
                    );
                });
                const cell = widget.closest('[bloomerp-component="detail-view-value"]');
                cell.addEventListener('bloomerp:detail-view-cell-change', () => {
                    widget.dataset.observedCellChanges = String(
                        Number(widget.dataset.observedCellChanges) + 1
                    );
                });
            }"""
        )

    def _select_planet(self, name: str, *, keyboard: bool = False) -> None:
        """Search the real endpoint and activate a result with native input events."""
        search = self._planet_widget().locator('input[type="text"]')

        def matches_search(response: Response) -> bool:
            """Wait for this query, rather than an earlier focus-triggered search."""
            parsed = urlsplit(response.url)
            return (
                "/components/search-objects/" in parsed.path
                and parse_qs(parsed.query).get("fk_search_results_query") == [name]
            )

        with self.page.expect_response(matches_search):
            search.fill(name)
        result = self.page.locator(
            ".foreign-field-dropdown:visible .foreign-field-results li[data-id]"
        ).filter(has_text=name)
        expect(result).to_have_count(1)
        expect(result).to_have_text(name)
        if keyboard:
            # Tab selects the first result; Shift+Tab returns to the input,
            # whose Enter handler activates it. Result li nodes do not
            # implement Enter activation themselves.
            search.press("Tab")
            expect(result).to_be_focused()
            self.page.keyboard.press("Shift+Tab")
            expect(search).to_be_focused()
            search.press("Enter")
        else:
            # Tab proves that the result being reparented actually owns focus.
            # Synthetic click events alone do not reproduce native focusout.
            search.press("Tab")
            expect(result).to_be_focused()
            result.click()
        expect(self.page.locator(".foreign-field-dropdown:visible")).to_have_count(0)
        self._expect_no_browser_errors()

    def _expect_relation_change(self, name: str, count: int) -> None:
        """Assert a single submitted value, public event counts, and visible Save."""
        widget = self._planet_widget()
        expected_id = str(self.PlanetModel.objects.get(name=name).pk)
        inputs = widget.locator('input[type="hidden"][name="planet"]')
        expect(inputs).to_have_count(1)
        expect(inputs).to_have_value(expected_id)
        expect(widget.locator(".foreign-field-badge")).to_have_count(1)
        expect(widget.locator(".foreign-field-badge")).to_contain_text(name)
        expect(widget).to_have_attribute("data-observed-widget-changes", str(count))
        expect(widget).to_have_attribute("data-observed-cell-changes", str(count))
        expect(self.form_host.locator("#object-crud-container-save-button")).to_be_visible()

    def _select_earth_with_mouse(self) -> None:
        """Check the native focused-result regression before any other field changes."""
        self._select_planet("Earth")
        self._expect_relation_change("Earth", 1)

    def _reselect_earth_with_mouse(self) -> None:
        """Ensure restoring the same result is safe and does not add dirty history."""
        self._select_planet("Earth")
        self._expect_relation_change("Earth", 1)

    def _clear_and_reset_relation(self) -> None:
        """Clear through the badge and use the actual CRUD Reset control."""
        widget = self._planet_widget()
        widget.locator(".foreign-field-selected button").click()
        expect(widget.locator('input[type="hidden"][name="planet"]')).to_have_value("")
        expect(widget.locator(".foreign-field-badge")).to_have_count(0)
        expect(widget).to_have_attribute("data-observed-widget-changes", "2")
        expect(widget).to_have_attribute("data-observed-cell-changes", "2")
        self.form_host.locator("#object-crud-container-reset-button").click()
        expect(widget.locator('input[type="text"]')).to_have_value("")
        expect(widget.locator('input[data-generated="true"]')).to_have_count(0)
        expect(self.form_host.locator("#object-crud-container-buttons")).to_be_hidden()
        self._expect_no_browser_errors()

    def _select_mars_with_keyboard(self) -> None:
        """Reselect after clear/reset and check that the empty sentinel is replaced."""
        self._select_planet("Mars", keyboard=True)
        self._expect_relation_change("Mars", 3)

    def _save_country(self) -> None:
        """Submit the real create form and verify database and modal return values."""
        name = "Native FK modal country" if self.in_modal else "Native FK page country"
        self.form_host.locator('input[name="name"][required]').fill(name)
        if self.in_modal:
            content_type = ContentType.objects.get_for_model(self.CountryModel)
            path = reverse(
                "components_create_object",
                kwargs={"content_type_id": content_type.pk},
            )
        else:
            path = reverse(get_create_view_url(self.CountryModel))
        with self.expect_response_for(path, method="POST") as pending:
            self.form_host.locator("#object-crud-container-save-button").click()
        self.assertEqual(pending.value.status, 204 if self.in_modal else 302)
        country = self.CountryModel.objects.get(name=name)
        self.assertEqual(country.planet.name, "Mars")
        if self.in_modal:
            expect(self.form_host).to_have_count(0)
            expect(
                self.page.locator(
                    '#main-content input[name="country"][data-generated="true"]'
                )
            ).to_have_value(str(country.pk))
